const userStats = `-- name: UserStats :one

with heard as (
  select count(*) as heard
  from stats_play_listeners l join stats_plays p on p.id = l.play_id
  where (p.guild_id = ?1 or ?1 is null) and l.user_id = ?2 and p.ok
), triggered as (
  select count(*) as triggered
  from stats_plays p
  where (p.guild_id = ?1 or ?1 is null) and p.user_id = ?2
    and p.trigger = 'command' and p.ok
), recent as (
  select p.at as last_heard
  from stats_play_listeners l join stats_plays p on p.id = l.play_id
  where (p.guild_id = ?1 or ?1 is null) and l.user_id = ?2 and p.ok
  order by p.at desc limit 1
), fled as (
  select count(*) as fled
  from stats_play_listeners l join stats_plays p on p.id = l.play_id
  where (p.guild_id = ?1 or ?1 is null) and l.user_id = ?2 and l.fled
)
select heard.heard, triggered.triggered, fled.fled, recent.last_heard
from heard
left join triggered on 1
left join fled      on 1
left join recent    on 1
`

type UserStatsParams struct {
	GuildID *int64 `json:"guild_id"`
	UserID  int64  `json:"user_id"`
}

type UserStatsRow struct {
	Heard     int64   `json:"heard"`
	Triggered *int64  `json:"triggered"`
	Fled      *int64  `json:"fled"`
	LastHeard *string `json:"last_heard"`
}

// Boards take a `since` text param computed in Go (” = all time), because sqlite can't build an
// interval from a bound integer inside datetime() the way Postgres' make_interval can.
// A null guild_id counts every guild.
func (q *Queries) UserStats(ctx context.Context, arg UserStatsParams) (UserStatsRow, error) {
	row := q.db.QueryRowContext(ctx, userStats, arg.GuildID, arg.UserID)
	var i UserStatsRow
	err := row.Scan(
		&i.Heard,
		&i.Triggered,
		&i.Fled,
		&i.LastHeard,
	)
	return i, err
}
